using UnityEngine;

namespace RailTracer
{
    // Which RVFX blood prefabs the game uses and how big they get. Generated by Editor/BloodSetup.cs into
    // Resources/Blood; swap prefabs or tweak sizes on the asset. Decals are parented to the carriage, so the
    // train starts clean and keeps every stain until restart.
    public class BloodKit : ScriptableObject
    {
        [Header("Transient")]
        public GameObject[] splashes;
        public GameObject[] goreSplashes;
        public GameObject[] gutBursts;
        public GameObject[] screens; // UI overlays shown when you're hit
        public float splashLife = 4f, screenLife = 1.5f;

        [Header("Persistent projected decals")]
        public GameObject[] decals;
        public float poolScale = 0.8f, spatterScale = 0.35f, smearScale = 0.45f, dripScale = 0.25f;
        [Header("Spray: rays from the chest, a stain wherever one hits (walls, seats, luggage, floor)")]
        public int brutalRays = 18, shotRays = 7, railRays = 7, quietRays = 3;
        public float sprayReach = 3.5f;  // metres
        [Range(0f, 2f)] public float sprayAway = 0.7f; // how much the spray leans away from the killer
        [Range(-1f, 1f)] public float sprayMaxRise = 0.3f; // highest a ray aims (y of its direction before normalising)
        [Range(0f, 1f)] public float sprayAlongRay = 0.5f; // stain angle: 0 = square-on to the surface, 1 = along the ray
        [Tooltip("How deep the projection box reaches through the surface (m). Shallow keeps it off nearby seat sides.")]
        public float projectDepth = 0.3f;
        [Tooltip("Projection depth for stains on window glass (m): inside the sash, clear of the wall faces it slides past.")]
        public float glassDepth = 0.03f;
        GameObject Spawn(GameObject[] set, Vector3 pos, Quaternion rot, Transform parent)
        {
            if (set == null || set.Length == 0) return null;
            var prefab = set[Random.Range(0, set.Length)];
            return prefab ? Instantiate(prefab, pos, rot, parent) : null;
        }

        public void Splash(Transform parent, Vector3 pos, Vector3 dir, bool gore)
        {
            // The camera only ever sees one side of the car, and a splash aimed at it shows its back: mirror any part
            // of the direction that points at the camera, so it still flies sideways but always away from the view.
            if (Camera.main)
            {
                var toCam = -Camera.main.transform.forward;
                toCam.y = 0;
                toCam.Normalize();
                float towards = Vector3.Dot(dir, toCam);
                if (towards > 0f) dir -= 2f * towards * toCam;
            }
            var rot = Quaternion.LookRotation(dir.sqrMagnitude > 1e-4f ? dir : Vector3.forward);
            var splash = Spawn(gore && goreSplashes.Length > 0 ? goreSplashes : splashes, pos, rot, parent);
            if (splash) Destroy(splash, splashLife);
            if (!gore) return;
            var guts = Spawn(gutBursts, pos, rot, null); // the chunks it throws clean themselves up
            if (guts) Destroy(guts, splashLife);
        }

        // A stain on whatever surface is at `surface`, projected along `facing`
        // (down for the floor, sideways onto seats and walls). Never removed.
        public void Decal(Transform parent, Vector3 surface, Vector3 facing, float scale, float depth = -1f)
        {
            float projectDepth = depth > 0f ? depth : this.projectDepth;
            scale *= Random.Range(0.8f, 1.2f);
            var rot = Quaternion.LookRotation(facing) * Quaternion.Euler(0, 0, Random.Range(0f, 360f));
            var pivot = surface - facing.normalized * (projectDepth * 0.5f); // centre the projection box on the surface
            var decal = Spawn(decals, pivot, rot, parent);
            if (!decal) return;
            // The projector inherits this scale; z turns its own depth (1.1 m on the RVFX prefabs) into projectDepth.
            var projector = decal.GetComponentInChildren<UnityEngine.Rendering.Universal.DecalProjector>();
            float prefabDepth = projector ? projector.size.z : 1f;
            decal.transform.localScale = new Vector3(scale, scale, projectDepth / prefabDepth);
        }

        // `rays` random directions from `origin`, leaning along `away` and kept low (nobody sees the ceiling); each hit
        // leaves a stain flat on that surface, smaller the further it flew.
        public void Spray(Transform parent, Vector3 origin, Vector3 away, int rays, float scale)
        {
            for (int i = 0; i < rays; i++)
            {
                var dir = Random.onUnitSphere + away * sprayAway;
                dir.y = Mathf.Clamp(dir.y, -1f, sprayMaxRise);
                if (!Physics.Raycast(origin, dir.normalized, out var hit, sprayReach, Physics.DefaultRaycastLayers, QueryTriggerInteraction.Ignore)) continue;
                if (hit.normal.y < -0.3f) continue; // ceilings and undersides
                // Between square-on to the surface and along the flight: part way splits a stain across a corner
                // (seat and backrest) instead of laying it flat on one face.
                var facing = Vector3.Slerp(-hit.normal, dir.normalized, sprayAlongRay);
                float s = scale * Mathf.Lerp(1f, 0.5f, hit.distance / sprayReach);
                // On a window: stuck to the sash so it slides with it, square-on and only as deep as the glass, so the
                // box never reaches the wall faces the sash drops past.
                var sash = hit.collider.GetComponentInParent<SlidingWindow>();
                if (sash) Decal(sash.transform, hit.point, -hit.normal, s, glassDepth);
                else Decal(parent, hit.point, facing, s);
            }
        }

        public void Screen(Transform canvas)
        {
            if (screens == null || screens.Length == 0 || !canvas) return;
            var prefab = screens[Random.Range(0, screens.Length)];
            if (!prefab) return;
            var overlay = Instantiate(prefab, canvas, false);
            Destroy(overlay, screenLife);
        }
    }
}
